UPDATE normal_group_creation_item_member


    SET creator_save_command_id = #{commandId},
        creator_saved_member_status = 'PENDING',


    SET member_save_command_id = #{commandId},
        member_saved_creator_status = 'PENDING',


    updated_at = #{now}
WHERE id = #{memberId}


    AND creator_saved_member_status = #{expectedStatus}


    AND member_saved_creator_status = #{expectedStatus}

UPDATE normal_group_creation_item_secondary_admin


    SET creator_save_command_id = #{commandId},
        creator_saved_secondary_status = 'PENDING',


    SET secondary_save_creator_command_id = #{commandId},
        secondary_saved_creator_status = 'PENDING',


    SET secondary_save_anchor_command_id = #{commandId},
        secondary_saved_anchor_status = 'PENDING',


    SET anchor_save_secondary_command_id = #{commandId},
        anchor_saved_secondary_status = 'PENDING',


    updated_at = #{now}
WHERE id = #{secondaryAdminId}


    AND creator_saved_secondary_status = #{expectedStatus}


    AND secondary_saved_creator_status = #{expectedStatus}


    AND secondary_saved_anchor_status = #{expectedStatus}


    AND anchor_saved_secondary_status = #{expectedStatus}

UPDATE normal_group_creation_item_member


    SET creator_saved_member_status = #{status},
        creator_save_error_code = #{errorCode},
        creator_save_error_message = #{errorMessage},


    SET member_saved_creator_status = #{status},
        member_save_error_code = #{errorCode},
        member_save_error_message = #{errorMessage},


    updated_at = #{now}
WHERE id = #{memberId}


    AND creator_save_command_id = #{commandId}
    AND creator_saved_member_status = 'PENDING'


    AND member_save_command_id = #{commandId}
    AND member_saved_creator_status = 'PENDING'

UPDATE normal_group_creation_item_secondary_admin


    SET creator_saved_secondary_status = #{status},


    SET secondary_saved_creator_status = #{status},


    SET secondary_saved_anchor_status = #{status},


    SET anchor_saved_secondary_status = #{status},


    last_error_code = #{errorCode}, last_error_message = #{errorMessage},
    updated_at = #{now}
WHERE id = #{secondaryAdminId}


    AND creator_save_command_id = #{commandId}
    AND creator_saved_secondary_status = 'PENDING'


    AND secondary_save_creator_command_id = #{commandId}
    AND secondary_saved_creator_status = 'PENDING'


    AND secondary_save_anchor_command_id = #{commandId}
    AND secondary_saved_anchor_status = 'PENDING'


    AND anchor_save_secondary_command_id = #{commandId}
    AND anchor_saved_secondary_status = 'PENDING'

UPDATE normal_group_creation_item_secondary_admin
SET participant_status = 'CONFIRMED', promotion_status = 'SUCCESS',
    last_error_code = NULL, last_error_message = NULL, updated_at = #{now}
WHERE item_id = #{itemId}
  AND participant_status = 'CONFIRMED'

UPDATE normal_group_creation_item_secondary_admin
SET promotion_status = 'FAILED', last_error_code = #{errorCode},
    last_error_message = #{errorMessage}, updated_at = #{now}
WHERE item_id = #{itemId}
  AND secondary_admin_ws_phone IN

    #{phone}

UPDATE normal_group_creation_item_member
SET participant_status = 'CONFIRMED', participant_raw_status = 'SUCCESS', updated_at = #{now}
WHERE item_id = #{itemId}
  AND creator_saved_member_status = 'SUCCESS'
  AND member_saved_creator_status = 'SUCCESS'

UPDATE normal_group_creation_item_secondary_admin
SET participant_status = 'CONFIRMED', updated_at = #{now}
WHERE item_id = #{itemId}
  AND creator_saved_secondary_status = 'SUCCESS'
  AND secondary_saved_creator_status = 'SUCCESS'

UPDATE normal_group_creation_item
SET settings_status = 'SUCCESS', current_step = 'LEAVING_GROUP',
    dispatch_stage = 'GROUP_LEAVE', dispatch_status = 'SENT',
    leave_command_id = #{leaveCommandId}, updated_at = #{now}
WHERE id = #{itemId}
  AND current_step = 'APPLYING_SETTINGS'
  AND settings_command_id = #{settingsCommandId}
  AND status = 'RUNNING'

UPDATE normal_group_creation_item
SET status = 'CREATED', current_step = 'DONE', dispatch_stage = 'NONE',
    dispatch_status = 'NONE', settings_status = 'SUCCESS',
    creator_leave_status = #{leaveStatus}, last_event_id = #{eventId},
    last_error_code = NULL, last_error_message = NULL, updated_at = #{now}
WHERE id = #{itemId}
  AND current_step = #{expectedStep}
  AND status = 'RUNNING'
  AND (
    (#{expectedStep} = 'APPLYING_SETTINGS' AND settings_command_id = #{commandId})
    OR (#{expectedStep} = 'LEAVING_GROUP' AND leave_command_id = #{commandId})
  )

UPDATE normal_group_creation_item
SET group_link_id = #{groupLinkId}, updated_at = #{now}
WHERE id = #{itemId}
  AND group_jid IS NOT NULL
